/**
 * Shader de la peinture metallique.
 *
 * ## L'idee mathematique
 *
 * Le relief n'est pas stocke : c'est un bruit de valeur lu sur un domaine
 * tres etire en abscisse, ce qui donne des stries — la trace du pinceau. La
 * normale s'en deduit par differences finies, deux lectures decalees, sans
 * texture ni carte.
 *
 * L'eclairage est un Blinn-Phong ordinaire, a ceci pres que la lampe n'est
 * pas dans la scene : elle est au pointeur, un peu au-dessus du plan. Bouger
 * le curseur revient donc a incliner la plaque sous une lampe fixe, et le
 * reflet balaie les stries dans le sens ou elles courent.
 *
 * Les paillettes sont une trame de points tires au hasard, tres fine, qui ne
 * s'allument que la ou le reflet porte deja : une paillette est un miroir
 * minuscule, elle ne brille pas dans l'ombre.
 *
 * ## Uniforms
 *
 * - `uTime` — temps en secondes, fourni par le moteur.
 * - `uResolution` — taille du canevas en pixels, fournie par le moteur.
 * - `uColorA` — le fond, sous la peinture.
 * - `uColorB` — le metal.
 * - `uColorC` — le reflet et les paillettes.
 * - `uPointer` — position amortie du pointeur, en coordonnees de texture.
 * - `uRelief` — profondeur des stries de brossage.
 * - `uSheen` — durete du reflet, entre zero et un.
 * - `uFlakes` — densite des paillettes, entre zero et un.
 */
export const METALLIC_PAINT_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform vec2 uPointer;
uniform float uRelief;
uniform float uSheen;
uniform float uFlakes;

float paintHash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Bruit de valeur : interpolation lissee entre les quatre coins de la cellule.
float paintNoise(vec2 p) {
  vec2 cell = floor(p);
  vec2 local = fract(p);
  vec2 smoothed = local * local * (3.0 - 2.0 * local);

  float a = paintHash(cell);
  float b = paintHash(cell + vec2(1.0, 0.0));
  float c = paintHash(cell + vec2(0.0, 1.0));
  float d = paintHash(cell + vec2(1.0, 1.0));

  return mix(mix(a, b, smoothed.x), mix(c, d, smoothed.x), smoothed.y);
}

// Le relief du brossage : deux octaves lus sur un domaine etire. L'etirement
// reste modere — au dela, les stries passent sous le pixel et ne se lisent
// plus que comme un fourmillement.
float brushed(vec2 p, float drift) {
  vec2 stretched = p * vec2(5.0, 110.0) + vec2(drift, 0.0);
  return paintNoise(stretched) * 0.66 + paintNoise(stretched * 0.37) * 0.34;
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vUv * vec2(aspect, 1.0);
  vec2 m = uPointer * vec2(aspect, 1.0);

  // La coulee : le domaine derive tres lentement, la plaque n'est pas figee.
  float drift = uTime * 0.03;
  float e = 0.0016;

  float h = brushed(p, drift);
  float hx = brushed(p + vec2(e, 0.0), drift);
  float hy = brushed(p + vec2(0.0, e), drift);

  // La normale par differences finies : la pente du relief, redressee.
  vec3 normal = normalize(vec3((h - hx) * uRelief, (h - hy) * uRelief, 1.0));

  // La lampe est au pointeur, un peu au-dessus du plan.
  vec3 light = normalize(vec3(m - p, 0.45));
  vec3 view = vec3(0.0, 0.0, 1.0);
  vec3 bisector = normalize(light + view);

  float diffuse = max(dot(normal, light), 0.0);
  float shine = pow(max(dot(normal, bisector), 0.0), mix(8.0, 55.0, clamp(uSheen, 0.0, 1.0)));

  // Le halo large : c'est lui qui dit ou est la lampe. Les stries seules ne
  // le diraient pas — elles renvoient partout un peu de lumiere.
  vec2 spread = (p - m) * vec2(0.7, 1.4);
  float halo = 1.0 - smoothstep(0.05, 0.75, length(spread));

  // Les paillettes : une trame grossiere, allumee seulement la ou le halo
  // porte deja. Une paillette est un miroir minuscule, pas une lampe.
  vec2 grain = floor(p * 170.0);
  float flake = step(1.0 - 0.10 * clamp(uFlakes, 0.0, 1.0), paintHash(grain));

  // Le metal reste proche du fond : une plaque qui couvre le cadre d'un gris
  // moyen rend illisible tout ce qu'on pose dessus.
  vec3 colour = mix(uColorA, uColorB, 0.12 + 0.26 * diffuse + 0.30 * halo);
  colour += uColorC * (shine * halo * 0.7 + flake * halo * 0.9 + halo * halo * 0.20);

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Peinture metallique : une plaque brossee et pailletee dont le reflet suit
 * le curseur.
 *
 * ## A quoi ce fond reagit
 *
 * Au deplacement du pointeur, avec amortissement : la lampe qui eclaire la
 * plaque est placee au curseur, un peu au-dessus du plan. Bouger le pointeur
 * revient donc a incliner la plaque, et le reflet balaie les stries de
 * brossage. A la sortie du cadre, le hook ramene la cible au centre.
 *
 * Ce qui distingue cette entree de `liquid-chrome` : le chrome y reflete un
 * studio fixe, sans pointeur, et sa surface ondule ; ici la surface est
 * plate, mate, striee, et c'est la lampe qui bouge. De `molten-metal` : le
 * bain y est chaud et coule. Et de `ferrofluid`, qui deforme sa matiere sous
 * le pointeur au lieu de l'eclairer.
 *
 * ## Le pont pointeur → shader
 *
 * Aucun rendu React par image : le composant mute en place un tableau stable
 * passe en uniform, et la surface relit ses uniforms a chaque image. La
 * recopie se fait dans la boucle du moteur, en priorite d'entree.
 *
 * ## Sous mouvement reduit
 *
 * La surface est refusee par le moteur et le repli statique s'affiche : le
 * suivi du pointeur est un agrement, pas un contenu.
 *
 * @module
 */

import {
  CLOCK_PRIORITY,
  clock,
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { useEffect, useRef, useState, type ReactElement } from 'react'

import { usePointerDamped } from '@registre/hooks/usePointerDamped'

import { METALLIC_PAINT_FRAGMENT } from './metallic-paint.shader.js'

/** Ce que l'echappatoire recoit. */
export interface MetallicPaintControls {
  /** Couleurs effectivement transmises au shader. */
  readonly colours: readonly ShaderColour[]
  /** Motif du refus, s'il y en a un. */
  readonly refused: string | undefined
}

/** Proprietes propres au composant. */
export interface MetallicPaintOwnProps {
  /** Profondeur des stries de brossage. @defaultValue 8 */
  relief?: number
  /** Durete du reflet, entre zero et un. @defaultValue 0.55 */
  sheen?: number
  /** Densite des paillettes, entre zero et un. @defaultValue 0.5 */
  flakes?: number
  /** Tokens dont les couleurs sont lues. */
  colors?: readonly string[]
  /** Classes du repli. */
  fallback?: string
  /** Echappatoire. */
  onReady?: ReadyCallback<MetallicPaintControls>
}

/** Toutes les proprietes. */
export type MetallicPaintProps = Customisable<MetallicPaintOwnProps>

/** Tokens employes par defaut : le fond, le metal, le reflet. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-theme-muted',
  '--o-palette-amber-200',
] as const

/** Repli par defaut : un degrade fige, dans les memes tons. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-tr o-from-zinc-50 dark:o-from-zinc-950 o-to-amber-100 dark:o-to-amber-950'

/**
 * Peinture metallique.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <MetallicPaint className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function MetallicPaint({
  relief = 8,
  sheen = 0.55,
  flakes = 0.5,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: MetallicPaintProps): ReactElement {
  const [host, setHost] = useState<HTMLDivElement | null>(null)

  // Tableau stable, mute en place : la surface relit les uniforms a chaque
  // image, l'identite ne change pas, la mutation suffit — aucun setState.
  const uPointer = useRef<number[]>([0.5, 0.5]).current

  // Vitesse 3 : une plaque a de l'inertie, le reflet ne saute pas.
  const pointer = usePointerDamped({ host, speed: 3, name: 'metallic-paint : pointeur' })

  useEffect(() => {
    const subscription = clock.subscribe(
      () => {
        // Du repere du hook (centre, y vers le bas) vers celui de la texture
        // (coin bas-gauche, y vers le haut).
        uPointer[0] = (pointer.current.x + 1) / 2
        uPointer[1] = 1 - (pointer.current.y + 1) / 2
      },
      { priority: CLOCK_PRIORITY.input, name: 'metallic-paint : pont' },
    )
    return () => subscription.unsubscribe()
  }, [pointer, uPointer])

  const {
    ref,
    setHost: setShaderHost,
    ready,
    refused,
    colours,
  } = useTokenShader<HTMLDivElement>({
    fragment: METALLIC_PAINT_FRAGMENT,
    colors,
    uniforms: { uPointer, uRelief: relief, uSheen: sheen, uFlakes: flakes },
    name: 'metallic-paint',
    // Les stries et les paillettes vivent sous le pixel a densite reduite :
    // elles s'y lisent comme un fourmillement. Le relief est adouci et les
    // paillettes coupees plutot que de laisser le bruit gagner.
    degrade: (quality) =>
      quality === 'low'
        ? { uRelief: relief * 0.5, uFlakes: 0 }
        : { uRelief: relief, uFlakes: flakes },
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        setShaderHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
